      "svg": "<svg viewBox=\"0 0 1100 1100\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" font-size=\"36\" fill=\"#ffd700\" font-weight=\"bold\" text-anchor=\"middle\">Quick Check</text><text x=\"550\" y=\"115\" font-size=\"24\" fill=\"#888\" text-anchor=\"middle\">The logic of repetition</text><rect x=\"80\" y=\"200\" width=\"940\" height=\"300\" rx=\"20\" fill=\"rgba(16,185,129,0.15)\" stroke=\"#10b981\" stroke-width=\"3\"/><text x=\"550\" y=\"260\" font-size=\"26\" fill=\"#10b981\" font-weight=\"bold\" text-anchor=\"middle\">Groundhog It</text><text x=\"550\" y=\"320\" font-size=\"21\" fill=\"#ffffff\" text-anchor=\"middle\">Same Highlight, repeated across days.</text><text x=\"550\" y=\"365\" font-size=\"21\" fill=\"#ffffff\" text-anchor=\"middle\">No re-deciding each morning.</text><text x=\"550\" y=\"430\" font-size=\"20\" fill=\"#888\" font-style=\"italic\" text-anchor=\"middle\">Decision fatigue drops. Output compounds.</text><rect x=\"80\" y=\"540\" width=\"940\" height=\"300\" rx=\"20\" fill=\"rgba(239,68,68,0.12)\" stroke=\"#ef4444\" stroke-width=\"3\"/><text x=\"550\" y=\"600\" font-size=\"26\" fill=\"#ef4444\" font-weight=\"bold\" text-anchor=\"middle\">Not This</text><text x=\"550\" y=\"660\" font-size=\"21\" fill=\"#ffffff\" text-anchor=\"middle\">A shiny new Highlight every day.</text><text x=\"550\" y=\"705\" font-size=\"21\" fill=\"#ffffff\" text-anchor=\"middle\">Nothing accumulates.</text><text x=\"550\" y=\"770\" font-size=\"20\" fill=\"#888\" font-style=\"italic\" text-anchor=\"middle\">Novelty feels good, builds little.</text><rect x=\"100\" y=\"1000\" width=\"900\" height=\"70\" rx=\"35\" fill=\"rgba(255,215,0,0.15)\" stroke=\"#ffd700\" stroke-width=\"3\"/><text x=\"550\" y=\"1045\" font-size=\"22\" fill=\"#ffd700\" font-weight=\"bold\" text-anchor=\"middle\">Repeat the same Highlight to make it compound.</text></svg>",
