"3\"/><text x=\"150\" y=\"735\" font-size=\"26\" fill=\"#ec4899\" font-weight=\"bold\" text-anchor=\"start\">4.</text><text x=\"200\" y=\"735\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"start\">Time caffeine. Last call at 2 p.m.</text><text x=\"200\" y=\"785\" font-size=\"19\" fill=\"#888\" text-anchor=\"start\">First cup 45 min after waking.</text><rect x=\"100\" y=\"840\" width=\"900\" height=\"130\" rx=\"20\" fill=\"rgba(139,92,246,0.12)\" stroke=\"#8b5cf6\" stroke-width=\"3\"/><text x=\"150\" y=\"900\" font-size=\"26\" fill=\"#8b5cf6\" font-weight=\"bold\" text-anchor=\"start\">5.</text><text x=\"200\" y=\"900\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"start\">Rate energy one to ten each night.</text><text x=\"200\" y=\"945\" font-size=\"19\" fill=\"#888\" text-anchor=\"start\">Keep the lever that moved it most.</text><rect x=\"100\" y=\"1000\" width=\"900\" height=\"70\" rx=\"35\" fill=\"rgba(255,215,0,0.15)\" stroke=\"#ffd700\" stroke-width=\"3\"/><text x=\"550\" y=\"1045\" font-size=\"22\" fill=\"#ffd700\" font-weight=\"bold\" text-anchor=\"middle\">Low motivation is often an uncharged battery.</text></svg>",
